for(const [id,target] of [['choose-certificate','certificate'],['choose-key','privateKey']])action(id,async()=>{if(!desktop)throw Error('Use the installed companion file picker.');const path=await desktop.chooseFile();if(path)$(target).value=path;});
function credentialFields(){$('secret-fields').hidden=$('auth-method').value!=='client-secret';$('certificate-fields').hidden=$('auth-method').value!=='certificate';$('client-secret').value='';}
$('auth-method').onchange=credentialFields;
action('connect',async()=>{const data={authMethod:$('auth-method').value,capabilities:[...document.querySelectorAll('#capabilities input:checked')].map(x=>x.value)};for(const id of ['tenant','clientId'])data[id]=$(id).value.trim();if(data.authMethod==='client-secret')data.clientSecret=$('client-secret').value;else for(const id of ['certificate','privateKey'])data[id]=$(id).value.trim();$('client-secret').value='';try{const result=await api('/connect',data);message(result.message);await refreshState();}finally{delete data.clientSecret;}});action('disconnect',async()=>{await api('/disconnect');await refreshState();message('Tenant disconnected. Restart AI clients to unload its connection. Local memories remain available.');});
action('check-capabilities',async()=>{const result=await api('/capability-preview',{live:true});$('capability-results').replaceChildren();if(result.connectionError)$('capability-results').append(el('p',result.connectionError,'error'));$('capability-results').append(el('p',result.explanation,'note'));for(const item of result.capabilities){const p=el('p',item.label+': '+item.state+(item.diagnostic?' · '+JSON.stringify(item.diagnostic):''),'note');$('capability-results').append(p);}});
async function activity(){await mentoring();const data=await api('/metrics');$('metrics').replaceChildren();for(const [title,value] of [['Retrievals',data.recalls??data.totalRecalls??0],['Added context bytes',data.recalledBytes??0],['Marked useful',data.accepted??0],['Marked irrelevant',data.irrelevant??0]]){const panel=el('div',undefined,'panel');panel.append(el('div',title,'eyebrow'),el('div',String(value),'stat'));$('metrics').append(panel);}$('recent-advice').replaceChildren();for(const item of data.recent||[]){const card=el('article',undefined,'memory');card.append(el('div',new Date(item.createdAt*1000).toLocaleString()+' · '+item.serializedBytes+' bytes'+(item.feedback?' · '+item.feedback:''),'meta'));for(const memory of item.memories||[])card.append(el('p',memory.content||'Memory no longer available.','rule'));const actions=el('div',undefined,'actions');for(const [label,value] of [['Useful','accepted'],['Ignored','ignored'],['Irrelevant','irrelevant']])actions.append(button(label,async()=>{await api('/feedback',{recallId:item.recallId,feedback:value});await activity();}));card.append(actions);$('recent-advice').append(card);}}action('refresh-activity',activity);action('clear-activity',async()=>{await api('/clear-metrics');await activity();message('Activity history cleared. Memories are unchanged.');});
async function startupPreference(){if(!desktop?.startup)return;const value=await desktop.startup();$('open-at-login').checked=value.enabled;$('open-at-login').disabled=!value.supported;}
