$('setup-prompt').value=FIRST_PROMPT;action('copy-setup-prompt',copyPrompt);action('home-try',async()=>{if((state.toolStatus||[]).some(t=>t.ready))await copyPrompt(state.memorySummary?.confirmed?WORK_PROMPT:FIRST_PROMPT);else displaySetup();});$('home-infrastructure').onclick=()=>view('infrastructure');$('open-setup').onclick=displaySetup;action('finish-setup',async()=>{await api('/setup-later');await refreshState();displayWorkspace();});$('retry-setup').onclick=displaySetup;
