action('enable-learning',async()=>{setupBusy=true;$('rescan-tools').disabled=true;$('setup-later').disabled=true;$('enable-learning').textContent='Configuring your tools…';for(const input of document.querySelectorAll('#setup-tools input'))input.disabled=true;message('Installing local memory connections and guidance, then checking each selected tool…');try{const clients=[...document.querySelectorAll('#setup-tools input:checked')].map(x=>x.value);const result=await api('/setup',{clients,mentor:true,enableLearning:true,updateMode:state.updateMode});await refreshState();showSetupResults(result,clients);}finally{setupBusy=false;$('rescan-tools').disabled=false;$('setup-later').disabled=false;renderTools('setup-tools',true);}});
function showSetupResults(result,clients){$('setup-choose').hidden=true;$('setup-finish').hidden=false;$('setup-step').textContent=result.configured?'READY FOR YOUR FIRST CONVERSATION':'REVIEW SETUP RESULTS';$('finish-eyebrow').textContent=result.configured?'CONFIGURATION CHECKED':'SOME TOOLS NEED ATTENTION';$('finish-title').textContent=result.configured?'Your tools are set up.':'Let’s finish connecting your tools.';$('finish-description').textContent=result.configured?'Fully quit and reopen your selected AI tools to load Greybeard. Then try your first conversation.':result.message;clients=result.selected||clients;results('setup-results',result.tools,clients);$('retry-setup').hidden=result.configured;$('finish-setup').hidden=false;$('finish-setup').textContent=result.configured?'Open my workspace':'Continue for now';$('first-conversation').hidden=!result.configured;message(result.error||'');window.scrollTo(0,0);}
async function reviewRepair(client,target,selected){repairPlan=await api('/repair-preview',{client});repairTarget=target;repairSelection=[...selected];$('repair-title').textContent='Reconnect '+client+'?';$('repair-details').replaceChildren(el('p','Configuration backup: '+repairPlan.configPath,'note'));for(const skill of repairPlan.skills)$('repair-details').append(el('p',skill.name+': '+skill.path,'note'));if(!repairPlan.skills.length)$('repair-details').append(el('p','No existing skill files need to be moved.','note'));$('repair-error').textContent='';$('repair-dialog').showModal();}
$('cancel-repair').onclick=()=>{$('repair-dialog').close();repairPlan=null;};
action('confirm-repair',async()=>{if(!repairPlan)return;const id=repairPlan.id;$('cancel-repair').disabled=true;try{const repaired=await api('/repair',{id});const result=await api('/setup',{clients:repairSelection,mentor:true,...(onboarding?{enableLearning:true}:{}),updateMode:state.updateMode});await refreshState();$('repair-dialog').close();repairPlan=null;if(onboarding)showSetupResults(result,repairSelection);else results(repairTarget,result.tools,repairSelection);message('Repair finished. Backups: '+repaired.backupPath+(result.configured?' · Restart your AI tools to load Greybeard.':' · Review any remaining issues.'));}catch(error){$('repair-error').textContent=error.message+' Close this dialog and review the repair again before retrying.';}finally{$('cancel-repair').disabled=false;}});
function mentorLabel(info){return ({paused:'Mentoring paused','disabled-in-host':'Hooks disabled in this tool','not-configured':'Automatic hooks need setup','awaiting-event':'Installed · awaiting first host event',error:'Host event received · local check needs attention',observed:'Host events received'})[info.status]||'Checking mentoring';}
async function mentoring(){const data=await api('/mentoring');const total=data.hosts.reduce((n,h)=>n+h.events,0);$('mentor-state').textContent=data.paused?'Mentoring is paused.':total?'Your tools are checking in.':'Waiting for your first event.';$('mentor-summary').textContent='Automatic checks run locally. Raw prompts and responses are not saved in activity. Recent event metadata is kept for '+data.retentionDays+' days. A received event does not prove the AI followed the advice.';$('mentor-hosts').replaceChildren();for(const tool of state.toolStatus||[]){if(!tool.detected||!tool.mentoring)continue;const observed=data.hosts.find(h=>h.host===tool.mentoring.host);const latest=data.recent.find(e=>e.host===tool.mentoring.host);const p=el('p',tool.name+': '+(data.paused?'Paused':tool.mentoring.disabled?'Hooks disabled in this tool':latest?.status==='error'?'Local mentoring needs attention, see Advice & activity':observed?'Last event '+new Date(observed.lastSeen).toLocaleString()+' · '+observed.events+' checks':mentorLabel(tool.mentoring)),'note');$('mentor-hosts').append(p);}$('automatic-events').replaceChildren();for(const event of data.recent){const card=el('article',undefined,'memory');card.append(el('div',event.host+' · '+event.event+' · '+event.status+' · '+new Date(event.createdAt).toLocaleString(),'meta'));for(const reminder of event.reminders)card.append(el('p',reminder,'note'));for(const memory of event.memories)card.append(el('p','Memory #'+memory.id+': '+memory.content,'rule'));if(event.candidateId)card.append(el('p','Proposed lesson #'+event.candidateId+' was saved for review. Check Your memory for its current status.','note'));if(event.diagnostic)card.append(el('p',event.diagnostic,'note'));$('automatic-events').append(card);}if(!data.recent.length)$('automatic-events').append(el('p','Send a prompt in a configured tool. For Codex, approve Greybeard in /hooks first.','note'));}
